def skill():
    num = den = Fraction(0)
    for r in (1, 3):
        pr = Fraction(1, 2)**3 * (3 if r == 1 else 1)
        den += pr
        if r == 1:
            num += pr * Fraction(1, 3)
        else:
            num += pr * (1 - Fraction(2, 3)**3)
    v = num / den
    return v.numerator + v.denominator

def standard():
    from itertools import product
    num = den = 0
    for t in product(range(1, 7), repeat=3):
        st = [1] * 6
        for k in t:
            if k <= 3:
                for i in range(3):
                    st[i] ^= 1
        if sum(st) == 3:
            den += 1
            if 1 in t:
                num += 1
    v = Fraction(num, den)
    return v.numerator + v.denominator

def unique():
    return [standard()]
